class Solution {
public:
    int arrayNesting(vector<int>& nums) {
        int n = nums.size();
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] != -1) {
                int count = 0;
                int j = i;
                while (nums[j] != -1) {
                    int next = nums[j];
                    nums[j] = -1;
                    j = next;
                    count++;
                }
                maxLen = max(maxLen, count);
            }
        }
        return maxLen;
    }
};
